package br.com.onda;
import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.webkit.*;
import android.widget.*;
import org.junit.*;
import static org.junit.Assert.*;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
import java.lang.reflect.*;
import java.util.*;

@androidx.media3.common.util.UnstableApi
public class YouTubeFavoritesTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private Activity owner,screen;private String old;private boolean had;private static final String VIDEO="https://m.youtube.com/watch?v=aqz-KE-bpKQ",SECOND="https://m.youtube.com/watch?v=abcdefghijk",PLAYLIST="https://m.youtube.com/playlist?list=RDaqz-KE-bpKQ";
 private Object get(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
 private void set(Object o,String name,Object v)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,v);}
 private interface Check{boolean ok()throws Exception;}
 private void waitFor(Check check)throws Exception{long end=SystemClock.elapsedRealtime()+15000;while(SystemClock.elapsedRealtime()<end){boolean[] ready={false};ins.runOnMainSync(()->{try{ready[0]=check.ok();}catch(Exception e){throw new RuntimeException(e);}});if(ready[0])return;Thread.sleep(100);}throw new AssertionError("YouTube favorites UI timed out");}
 private EditText input(View root){if(root instanceof EditText)return (EditText)root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){EditText e=input(((ViewGroup)root).getChildAt(i));if(e!=null)return e;}return null;}
 @Before public void before(){SharedPreferences p=c.getSharedPreferences(YouTubeFavorites.PREF,0);had=p.contains(YouTubeFavorites.KEY);old=p.getString(YouTubeFavorites.KEY,"");p.edit().clear().commit();}
 @After public void after(){ins.runOnMainSync(()->{if(screen!=null&&!screen.isDestroyed())screen.finish();if(owner!=null&&!owner.isDestroyed())owner.finish();});ins.waitForIdleSync();SharedPreferences.Editor e=c.getSharedPreferences(YouTubeFavorites.PREF,0).edit().clear();if(had)e.putString(YouTubeFavorites.KEY,old);e.commit();}
 private void fixture(String url)throws Exception{ins.runOnMainSync(()->{try{set(owner,"lastUrl",url);set(owner,"pendingUrl",url);WebView web=(WebView)get(owner,"web");web.stopLoading();web.loadDataWithBaseURL(url,"<html><head><title>Chitãozinho – YouTube</title></head><body>Onda fixture</body></html>","text/html","UTF-8",url);}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->((Button)get(owner,"favorite")).isEnabled());}
 @Test public void savesCurrentPageThroughDialogAndKeepsDeviceFavoritesSeparate()throws Exception{Set<String> local=new HashSet<>(c.getSharedPreferences("library",0).getStringSet("favorites",Collections.emptySet()));owner=ins.startActivitySync(new Intent(c,YouTubeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));fixture(VIDEO);ins.runOnMainSync(()->{try{((Button)get(owner,"favorite")).performClick();AlertDialog dialog=(AlertDialog)get(owner,"saveDialog");EditText name=input(dialog.getWindow().getDecorView());assertEquals("Chitãozinho",name.getText().toString());name.setText("Minha música online");}catch(Exception e){throw new RuntimeException(e);}});ins.waitForIdleSync();ins.runOnMainSync(()->{try{((AlertDialog)get(owner,"saveDialog")).getButton(AlertDialog.BUTTON_POSITIVE).performClick();}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->YouTubeFavorites.read(c).items.size()==1);ins.runOnMainSync(()->{try{assertEquals(1,YouTubeFavorites.read(c).items.size());assertTrue(((Button)get(owner,"favorite")).getText().toString().contains("Favoritado"));((WebView)get(owner,"web")).getWebViewClient().onPageFinished((WebView)get(owner,"web"),"https://m.youtube.com/");assertEquals(VIDEO,get(owner,"lastUrl"));}catch(Exception e){throw new RuntimeException(e);}});assertEquals(local,c.getSharedPreferences("library",0).getStringSet("favorites",Collections.emptySet()));}
 @Test public void searchesRenamesRemovesAndOpensBookmarkInsideExistingBrowser()throws Exception{YouTubeFavorites.save(c,VIDEO,"Chitãozinho favorito");YouTubeFavorites.save(c,PLAYLIST,"Playlist de estudo");owner=ins.startActivitySync(new Intent(c,YouTubeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Instrumentation.ActivityMonitor m=ins.addMonitor(YouTubeFavoritesActivity.class.getName(),null,false);ins.runOnMainSync(()->{try{((Button)get(owner,"favorites")).performClick();}catch(Exception e){throw new RuntimeException(e);}});screen=m.waitForActivityWithTimeout(15000);ins.removeMonitor(m);assertNotNull(screen);waitFor(()->get(owner,"web")==null);ins.runOnMainSync(()->{try{((EditText)get(screen,"search")).setText("chitaozinho");ListView list=(ListView)get(screen,"list");assertEquals(1,list.getAdapter().getCount());list.getOnItemLongClickListener().onItemLongClick(list,null,0,0);AlertDialog options=(AlertDialog)get(screen,"optionsDialog");options.getListView().performItemClick(null,0,0);}catch(Exception e){throw new RuntimeException(e);}});ins.waitForIdleSync();ins.runOnMainSync(()->{try{AlertDialog edit=(AlertDialog)get(screen,"editDialog");input(edit.getWindow().getDecorView()).setText("Canção favorita");edit.getButton(AlertDialog.BUTTON_POSITIVE).performClick();}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->"Canção favorita".equals(YouTubeFavorites.read(c).find(VIDEO).title));ins.runOnMainSync(()->{try{ListView list=(ListView)get(screen,"list");assertEquals("Canção favorita",YouTubeFavorites.read(c).find(VIDEO).title);((EditText)get(screen,"search")).setText("Playlist de estudo");list.getOnItemLongClickListener().onItemLongClick(list,null,0,0);((AlertDialog)get(screen,"optionsDialog")).getListView().performItemClick(null,1,1);assertNull(YouTubeFavorites.read(c).find(PLAYLIST));((EditText)get(screen,"search")).setText("Canção favorita");assertEquals(1,list.getAdapter().getCount());list.performItemClick(null,0,0);}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->VIDEO.equals(get(owner,"lastUrl"))&&get(owner,"web")!=null);ins.runOnMainSync(()->{try{assertTrue(((WebView)get(owner,"web")).getSettings().getMediaPlaybackRequiresUserGesture());assertEquals(1,YouTubeFavorites.read(c).items.size());}catch(Exception e){throw new RuntimeException(e);}});}
 @Test public void preservesUnknownDataAndResourceNavigationGuards(){String raw="{\"version\":9,\"items\":[]}";c.getSharedPreferences(YouTubeFavorites.PREF,0).edit().putString(YouTubeFavorites.KEY,raw).commit();assertFalse(YouTubeFavorites.save(c,VIDEO,"X"));assertFalse(YouTubeFavorites.remove(c,VIDEO));assertEquals(raw,c.getSharedPreferences(YouTubeFavorites.PREF,0).getString(YouTubeFavorites.KEY,""));assertTrue(YouTubeActivity.matchesPending(VIDEO,VIDEO+"&feature=share"));assertFalse(YouTubeActivity.matchesPending(VIDEO,SECOND));assertTrue(YouTubeActivity.matchesPending(PLAYLIST,PLAYLIST+"&si=test"));assertFalse(YouTubeActivity.matchesPending(PLAYLIST,"https://m.youtube.com/playlist?list=PLabcdefghijk"));}
}
